# SCX standalone v0.1.0-alpha.7
# Generated by scripts/build_standalone.py; source this one file.
# No SCX package, compiler, Python, subprocess, or automatic installation.
(function(.target) {
SCX_VERSION <- "v0.1.0-alpha.7"
  required <- c("SeuratObject", "Matrix", "jsonlite", "digest")
  missing <- required[!vapply(required, requireNamespace, logical(1), quietly = TRUE)]
  if (length(missing)) stop("Existing Seurat environment is missing: ", paste(missing, collapse=", "),
    ". No packages were installed. Use an environment containing these dependencies.")
  if (packageVersion("SeuratObject") < "5.0.0") stop("SeuratObject >=5 is required")
.scx_exists <- function(path) file.exists(path) || dir.exists(path) || .scx_symlink(path)
.scx_symlink <- function(path) isTRUE(.scx_native("scx_is_link", path))

.scx_output_path <- function(path) {
  dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
  file.path(normalizePath(dirname(path), winslash = "/", mustWork = TRUE), basename(path))
}

.scx_lock_path <- function(path) {
  path <- file.path(normalizePath(dirname(path), winslash = "/", mustWork = TRUE), basename(path))
  # Same lock identity as Python 0.1.0a5 (including Windows case/separators).
  key <- if (.Platform$OS.type == "windows") tolower(chartr("/", "\\", path)) else path
  file.path(dirname(path), paste0(".scx-lock-", substr(digest::digest(charToRaw(enc2utf8(key)),
             algo = "sha256", serialize = FALSE), 1L, 20L)))
}

.scx_destination <- function(path, overwrite) {
  if (.scx_symlink(path)) stop("output symlinks are refused: ", path)
  if (.scx_exists(path)) {
    if (!overwrite) stop("output already exists: ", path, "; choose a new path or use overwrite = TRUE")
    if (!dir.exists(path)) stop("output must be an SCX directory: ", path)
    .scx_manifest(path)  # Refuse unrelated directories, even with opt-in.
  }
}

.scx_resource <- function(path, code) {
  tryCatch(withCallingHandlers(force(code), warning = function(w) stop(conditionMessage(w), call. = FALSE)),
           error = function(e) stop(path, ": ", conditionMessage(e), call. = FALSE))
}

.scx_safe_path <- function(root, relative) {
  if (length(relative) != 1L || is.na(relative) || !nzchar(relative) ||
      grepl("[\\\\:\t\r\n]", relative) || startsWith(relative, "/") ||
      any(strsplit(relative, "/", fixed = TRUE)[[1]] %in% c("", ".", "..")) || endsWith(relative, "/"))
    stop("unsafe manifest path: ", relative)
  target <- file.path(root, relative)
  resolved <- normalizePath(target, winslash = "/", mustWork = FALSE)
  base <- normalizePath(root, winslash = "/", mustWork = TRUE)
  if (.Platform$OS.type == "windows") { resolved <- tolower(resolved); base <- tolower(base) }
  if (!startsWith(resolved, paste0(base, "/"))) stop("manifest path escapes dataset: ", relative)
  target
}

.scx_table_lines <- function(lines) {
  if (!length(lines) || anyNA(iconv(lines, from = "UTF-8", to = "UTF-8", sub = NA))) stop("empty or invalid UTF-8 table")
  con <- textConnection(lines); on.exit(close(con))
  width <- count.fields(con, sep = "\t", quote = '"', comment.char = "", blank.lines.skip = FALSE)
  if (anyNA(width) || any(width != width[1]) || width[1] < 1L) stop("invalid table width or quoted newline")
  table <- read.delim(text = lines, check.names = FALSE, stringsAsFactors = FALSE, colClasses = "character",
                      na.strings = NULL, comment.char = "", fill = FALSE, blank.lines.skip = FALSE)
  if (anyDuplicated(names(table)) || any(!nzchar(names(table))) ||
      any(grepl("[\t\r\n]", c(names(table), unlist(table, use.names = FALSE)))))
    stop("table headers must be nonempty/unique; literal tabs/newlines are unsupported")
  table
}

.scx_table <- function(path, compressed = TRUE) .scx_resource(path, {
  if (compressed) .scx_native("scx_check_gzip", path)
  con <- if (compressed) gzfile(path, "rt", encoding = "UTF-8") else file(path, "rt", encoding = "UTF-8")
  on.exit(close(con))
  .scx_table_lines(readLines(con, warn = FALSE))
})

.scx_manifest <- function(root) .scx_resource(file.path(root, "manifest.tsv"), {
  path <- .scx_safe_path(root, "manifest.tsv")
  con <- file(path, "rt", encoding = "UTF-8"); on.exit(close(con))
  if (!identical(readLines(con, 1L, warn = FALSE), "# scx_version=0.1-alpha")) stop("missing or unsupported manifest version")
  manifest <- .scx_table_lines(readLines(con, warn = FALSE))
  if (!identical(names(manifest), c("path", "role", "name"))) stop("manifest header must be path, role, name")
  if (anyDuplicated(manifest$path) || anyDuplicated(manifest[c("role", "name")])) stop("duplicate manifest path or role/name")
  roles <- c("cells", "features", "counts", "normalized", "embedding", "cell_graph", "metadata_schema")
  if (any(!manifest$role %in% roles) || any(!grepl("^[A-Za-z0-9_.-]+$", manifest$name))) stop("invalid role or name")
  for (p in manifest$path) .scx_safe_path(root, p)
  for (role in c("cells", "features", "counts")) {
    row <- manifest[manifest$role == role, , drop = FALSE]
    expected <- switch(role, cells = "cells.tsv.gz", features = "features.tsv.gz", counts = "matrices/counts.mtx.gz")
    if (nrow(row) != 1L || row$path != expected || row$name != role) stop("required manifest entry invalid: ", role)
  }
  if (sum(manifest$role == "normalized") > 1L) stop("only one normalized matrix supported")
  row <- manifest[manifest$role == "metadata_schema", , drop = FALSE]
  if (nrow(row) > 1L || (nrow(row) && (row$path != "metadata.schema.json" || row$name != "metadata")))
    stop("invalid metadata schema manifest entry")
  manifest
})

.scx_matrix <- function(path, shape) .scx_resource(path, {
  .scx_native("scx_check_gzip", path)
  con <- gzfile(path, "rt", encoding = "UTF-8"); on.exit(close(con))
  header <- strsplit(tolower(trimws(readLines(con, 1L, warn = FALSE))), "[[:space:]]+")[[1]]
  if (length(header) != 5L || !identical(header[c(1, 2, 3, 5)], c("%%matrixmarket", "matrix", "coordinate", "general")) ||
      !header[4] %in% c("integer", "real")) stop("matrix must use Matrix Market coordinate real/integer general")
  repeat {
    line <- readLines(con, 1L, warn = FALSE)
    if (!length(line)) stop("missing matrix dimensions")
    if (nzchar(trimws(line)) && !startsWith(trimws(line), "%")) break
  }
  fields <- strsplit(trimws(line), "[[:space:]]+")[[1]]
  if (length(fields) != 3L || any(!grepl("^[0-9]+$", fields))) stop("invalid matrix dimensions")
  dims <- as.numeric(fields)
  if (any(!is.finite(dims)) || any(dims > .Machine$integer.max) || any(dims[1:2] != shape)) stop("matrix dimensions do not match canonical axes or exceed R limits")
  n <- dims[3]
  entries <- if (n) scan(con, what = list(i = integer(), j = integer(), x = numeric()), nmax = n,
                         quiet = TRUE, multi.line = FALSE, comment.char = "%") else list(i = integer(), j = integer(), x = numeric())
  if (length(entries$x) != n) stop("truncated MTX: declared entry count does not match data")
  repeat {
    remaining <- readLines(con, 10000L, warn = FALSE)
    if (!length(remaining)) break
    if (any(nzchar(trimws(remaining)) & !startsWith(trimws(remaining), "%"))) stop("extra entries after declared MTX count")
  }
  if (anyNA(entries$i) || anyNA(entries$j) || any(entries$i < 1L | entries$i > dims[1]) ||
      any(entries$j < 1L | entries$j > dims[2])) stop("MTX index out of bounds")
  if (any(!is.finite(entries$x))) stop("matrix values must be finite")
  if (header[4] == "integer" && any(entries$x != trunc(entries$x) | abs(entries$x) > 2^53 - 1))
    stop("integer MTX value cannot be represented exactly in native R")
  if (header[4] == "integer" && sum(abs(entries$x)) > 2^53 - 1) {
    bounds <- Matrix::sparseMatrix(i = entries$i, j = entries$j, x = abs(entries$x), dims = as.integer(dims[1:2]))
    if (any(.scx_values(bounds) > 2^53 - 1)) stop("integer duplicate group can lose native R precision")
    rm(bounds)
  }
  x <- Matrix::sparseMatrix(i = entries$i, j = entries$j, x = entries$x, dims = as.integer(dims[1:2]))
  if (any(!is.finite(.scx_values(x)))) stop("nonfinite summed matrix values")
  if (header[4] == "integer" && any(abs(.scx_values(x)) > 2^53 - 1)) stop("summed integer MTX value exceeds native R exact range")
  x
})

.scx_keys <- function(x, keys) {
  is.list(x) && !anyDuplicated(names(x)) && setequal(names(x), keys)
}
.scx_text <- function(x) is.character(x) && length(x) == 1L && !is.na(x)

.scx_check_values <- function(values, dtype, tokens = NULL) {
  supported <- c("object", "str", "string", "bool", "boolean", "float32", "Float32", "float64", "Float64",
                 "int8", "Int8", "int16", "Int16", "int32", "Int32", "uint8", "UInt8", "uint16", "UInt16")
  if (!.scx_text(dtype) || !dtype %in% supported) stop("SCX dtype not safely representable in native R: ", paste(dtype, collapse = "/"))
  missing <- vapply(values, is.null, logical(1))
  present <- values[!missing]
  scalar <- function(v) length(v) == 1L && !is.list(v) && !is.na(v)
  if (any(!vapply(present, scalar, logical(1)))) stop("metadata must contain JSON scalars or null")
  if (dtype %in% c("object", "str", "string")) {
    if (any(!vapply(present, is.character, logical(1)))) stop("string metadata contains a non-string value")
  } else if (dtype %in% c("bool", "boolean")) {
    if (any(!vapply(present, is.logical, logical(1))) || (dtype == "bool" && any(missing))) stop("boolean metadata requires true/false and valid nullability")
  } else {
    if (any(!vapply(present, is.numeric, logical(1)))) stop("numeric metadata requires JSON numbers")
    numbers <- unlist(present, use.names = FALSE)
    if (any(!is.finite(numbers))) stop("nonfinite numeric metadata")
    if (grepl("[Ii]nt", dtype)) {
      if (!is.null(tokens) && any(!grepl("^-?(0|[1-9][0-9]*)$", tokens[!missing]))) stop("integer metadata requires JSON integer tokens")
      bits <- as.numeric(sub(".*?([0-9]+)$", "\\1", dtype))
      unsigned <- startsWith(tolower(dtype), "u")
      low <- if (unsigned) 0 else -2^(bits - 1)
      high <- if (unsigned) 2^bits - 1 else 2^(bits - 1) - 1
      if (any(numbers != trunc(numbers) | numbers < low | numbers > high)) stop("integer metadata overflow or fraction")
      if (any(numbers == -.Machine$integer.max - 1)) stop("R cannot represent INT_MIN without losing missingness")
      if (grepl("^(int|uint)", dtype) && any(missing)) stop("nonnullable integer contains null")
    } else {
      if (grepl("32$", dtype) && length(numbers)) {
        rounded <- readBin(writeBin(as.double(numbers), raw(), size = 4L), "double", n = length(numbers), size = 4L)
        if (any(!is.finite(rounded) | rounded != numbers)) stop("lossy float32 metadata cast")
      }
      if (!is.null(tokens)) {
        integer_token <- grepl("^-?(0|[1-9][0-9]*)$", tokens[!missing])
        if (any(integer_token & sprintf("%.0f", numbers) != tokens[!missing] & tokens[!missing] != "-0"))
          stop("integer JSON value loses precision in floating dtype")
      }
    }
  }
  invisible(NULL)
}

.scx_metadata <- function(table, spec, key) {
  if (is.null(spec)) return(.scx_decode_frame(table, NULL))
  if (!.scx_keys(spec, c("index_name", "columns")) ||
      (!is.null(spec$index_name) && !.scx_text(spec$index_name)) || !is.list(spec$columns)) stop("invalid metadata table schema")
  names <- vapply(spec$columns, function(x) {
    if (!is.list(x) || !.scx_text(x$name)) stop("invalid metadata column descriptor")
    x$name
  }, character(1))
  if (!identical(colnames(table), c(key, names))) stop("metadata schema columns do not match TSV")
  for (column in spec$columns) {
    tokens <- table[[column$name]]
    values <- jsonlite::fromJSON(paste0("[", paste(tokens, collapse = ","), "]"), simplifyVector = FALSE)
    if (identical(column$dtype, "category")) {
      if (!.scx_keys(column, c("name", "dtype", "ordered", "categories_dtype", "categories")) ||
          !is.logical(column$ordered) || length(column$ordered) != 1L || is.na(column$ordered) || !is.list(column$categories)) stop("invalid categorical schema")
      .scx_check_values(column$categories, column$categories_dtype)
      if (!column$categories_dtype %in% c("object", "str", "string")) stop("numeric/boolean categorical levels are unsupported by R factors")
      if (any(vapply(column$categories, is.null, logical(1))) || anyDuplicated(unlist(column$categories))) stop("categories must be nonmissing and unique")
      missing <- vapply(values, is.null, logical(1))
      codes <- unlist(values[!missing], use.names = FALSE)
      if (any(!grepl("^(0|[1-9][0-9]*)$", tokens[!missing])) ||
          any(!vapply(values[!missing], is.numeric, logical(1))) ||
          any(codes < 0 | codes >= length(column$categories))) stop("categorical code out of range or wrong type")
    } else {
      if (!.scx_keys(column, c("name", "dtype"))) stop("invalid column schema")
      .scx_check_values(values, column$dtype, tokens)
    }
  }
  .scx_decode_frame(table, spec)
}

.scx_inspect <- function(path, retain = FALSE, retain_expression = NULL) {
  path <- normalizePath(path, winslash = "/", mustWork = TRUE)
  manifest <- .scx_manifest(path)
  for (relative in manifest$path) if (!file.exists(.scx_safe_path(path, relative))) stop("missing file: ", file.path(path, relative))
  cells <- .scx_table(file.path(path, "cells.tsv.gz"))
  features <- .scx_table(file.path(path, "features.tsv.gz"))
  for (pair in list(list(cells, "cell_id"), list(features, "feature_id"))) {
    .scx_resource(file.path(path, if (pair[[2]] == "cell_id") "cells.tsv.gz" else "features.tsv.gz"), {
      if (!nrow(pair[[1]]) || names(pair[[1]])[1] != pair[[2]]) stop("invalid nonempty canonical ID column: ", pair[[2]])
      .scx_ids(pair[[1]][[1]])
    })
  }
  schema <- NULL
  if (!"metadata_schema" %in% manifest$role) warning("Legacy SCX metadata have no dtype schema; loading as text")
  if ("metadata_schema" %in% manifest$role) schema <- .scx_resource(file.path(path, "metadata.schema.json"), {
    spec <- jsonlite::fromJSON(file.path(path, "metadata.schema.json"), simplifyVector = FALSE)
    if (!.scx_keys(spec, c("schema_version", "cells", "features")) || !identical(spec$schema_version, "1.0") ||
        !.scx_keys(spec$cells, c("index_name", "columns")) || !.scx_keys(spec$features, c("index_name", "columns")))
      stop("invalid or unsupported metadata schema")
    spec
  })
  meta <- .scx_resource(file.path(path, "cells.tsv.gz"), .scx_metadata(cells, if (is.null(schema)) NULL else schema$cells, "cell_id"))
  feature_meta <- .scx_resource(file.path(path, "features.tsv.gz"), .scx_metadata(features, if (is.null(schema)) NULL else schema$features, "feature_id"))
  payload <- list(manifest = manifest, cells = cells[[1]], features = features[[1]], meta = meta, feature_meta = feature_meta,
                  matrices = list(), embeddings = list())
  shape <- c(nrow(cells), nrow(features))
  for (i in seq_len(nrow(manifest))) {
    row <- manifest[i, ]; file <- .scx_safe_path(path, row$path)
    if (row$role %in% c("counts", "normalized", "cell_graph")) {
      x <- .scx_matrix(file, if (row$role == "cell_graph") rep(shape[1], 2L) else shape)
      if (row$role == "counts" && any(.scx_values(x) < 0)) stop(file, ": counts must be nonnegative")
      if (retain || identical(row$role, retain_expression)) payload$matrices[[row$path]] <- x
      rm(x)
    } else if (row$role == "embedding") {
      table <- .scx_table(file)
      .scx_resource(file, {
        if (ncol(table) < 2L || names(table)[1] != "cell_id" || !identical(table[[1]], cells[[1]])) stop("invalid embedding cell axis")
        values <- matrix(as.numeric(as.matrix(table[-1])), nrow = shape[1])
        if (any(!is.finite(values))) stop("embedding must be numeric and finite")
        if (retain) payload$embeddings[[row$path]] <- values
      })
    }
  }
  if (retain || !is.null(retain_expression)) payload else list(cells = shape[1], features = shape[2], files = nrow(manifest))
}

#' Validate the R-readable SCX profile without Python.
#' @export
validate_scx <- function(path) .scx_inspect(path)

.scx_json <- function(x) as.character(jsonlite::toJSON(x, auto_unbox = TRUE, na = "null", null = "null", digits = 17))

.scx_column_json <- function(values) {
  if (is.integer(values)) {
    encoded <- as.character(values)
  } else if (is.double(values)) {
    encoded <- sprintf("%.17g", values)
  } else if (is.logical(values)) {
    encoded <- ifelse(values, "true", "false")
  } else {
    # Repeated text is encoded once per unique value; jsonlite still handles
    # escaping rather than treating R string escapes as JSON escapes.
    unique_values <- unique(values)
    encoded_unique <- vapply(seq_along(unique_values), function(i) .scx_json(unique_values[i]), character(1))
    encoded <- encoded_unique[match(values, unique_values)]
  }
  encoded[is.na(values)] <- "null"
  unname(encoded)
}

.scx_tsv <- function(x, path) {
  dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
  con <- gzfile(path, "wt", encoding = "UTF-8")
  on.exit(close(con))
  write.table(x, con, sep = "\t", row.names = FALSE, quote = TRUE, qmethod = "double", na = "")
}

.scx_read_tsv <- function(path) {
  .scx_table(path)
}

.scx_mtx <- function(x, path) {
  dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
  x <- methods::as(Matrix::Matrix(x, sparse = TRUE), "generalMatrix")
  x <- methods::as(methods::as(x, "dMatrix"), "TsparseMatrix")
  output <- gzfile(path, "wt", encoding = "UTF-8"); on.exit(close(output))
  # Matrix::writeMM auto-selects pattern/symmetric even for general matrices.
  # SCX requires numeric coordinate general, including all directed entries.
  writeLines(c("%%MatrixMarket matrix coordinate real general", "% SCX CELL x FEATURE or CELL x CELL",
               paste(nrow(x), ncol(x), length(x@x))), output)
  if (length(x@x)) for (start in seq.int(1L, length(x@x), by = 100000L)) {
    take <- start:min(start + 99999L, length(x@x))
    writeLines(paste(x@i[take] + 1L, x@j[take] + 1L, sprintf("%.17g", x@x[take])), output)
  }
}

.scx_ids <- function(ids) {
  if (is.null(ids) || anyNA(ids) || any(!nzchar(ids)) || anyDuplicated(ids) ||
      any(grepl("[\t\r\n]", ids))) stop("IDs must be unique nonempty text without tabs/newlines")
}

.scx_name <- function(name) {
  if (length(name) != 1L || !grepl("^[A-Za-z0-9_.-]+$", name)) stop("unsafe SCX object name")
}

.scx_meta <- function(frame, ids, key, path) {
  if (!is.data.frame(frame) || !identical(rownames(frame), ids)) stop("metadata cell/feature axis mismatch")
  if (anyDuplicated(names(frame)) || any(!nzchar(names(frame))) || key %in% names(frame) ||
      any(grepl("[\t\r\n]", names(frame)))) stop("invalid or reserved metadata column name")
  table <- data.frame(ids, check.names = FALSE); names(table) <- key
  columns <- lapply(names(frame), function(name) {
    x <- frame[[name]]
    if (is.factor(x)) {
      if (anyNA(levels(x))) stop("factor levels must be nonmissing")
      spec <- list(name = name, dtype = "category", ordered = is.ordered(x),
                   categories_dtype = "object", categories = as.list(levels(x)))
      values <- as.integer(x) - 1L
    } else {
      dtype <- if (is.integer(x) && !is.object(x)) {
        if (anyNA(x)) "Int32" else "int32"
      } else if (is.double(x) && !is.object(x)) {
        if (any(is.infinite(x))) stop("metadata infinity unsupported")
        "float64"
      } else if (is.logical(x) && !is.object(x)) {
        if (anyNA(x)) "boolean" else "bool"
      } else if (is.character(x) && !is.object(x)) "object" else stop("unsupported R metadata class: ", paste(class(x), collapse = "/"))
      spec <- list(name = name, dtype = dtype)
      values <- x
    }
    table[[name]] <<- .scx_column_json(values)
    spec
  })
  .scx_tsv(table, path)
  list(index_name = NULL, columns = columns)
}

.scx_aligned <- function(x, rows, cols = NULL) {
  if (!setequal(rownames(x), rows) || nrow(x) != length(rows)) stop("row axis does not cover canonical IDs")
  if (is.null(cols)) return(x[rows, , drop = FALSE])
  if (!setequal(colnames(x), cols) || ncol(x) != length(cols)) stop("column axis does not cover canonical IDs")
  x[rows, cols, drop = FALSE]
}

.scx_values <- function(x) {
  # Implicit sparse zeros are finite and nonnegative. Checking the whole sparse
  # matrix with is.finite() can materialize a dense CELL x CELL logical matrix.
  if (inherits(x, "sparseMatrix")) {
    if ("x" %in% methods::slotNames(x)) return(methods::slot(x, "x"))
    return(1)  # Pattern matrix: stored entries are implicit ones.
  }
  x
}

#' Export a single Seurat assay with validated, rollback-safe publication.
#' @export
write_scx_seurat <- function(object, path, assay = SeuratObject::DefaultAssay(object),
                             counts_layer = "counts", normalized_layer = "data",
                             reductions = SeuratObject::Reductions(object),
                             graphs = SeuratObject::Graphs(object), overwrite = FALSE,
                             python = NULL, warn_scope = TRUE) {
  if (!inherits(object, "Seurat")) stop("object must be Seurat")
  if (!is.logical(overwrite) || length(overwrite) != 1L || is.na(overwrite)) stop("overwrite must be TRUE or FALSE")
  if ((file.exists(path) || dir.exists(path)) && !overwrite) stop("output already exists; choose a new path or use overwrite = TRUE")
  # Kept for source compatibility; no Python executable is inspected or invoked.
  if (!assay %in% SeuratObject::Assays(object)) stop("unknown assay")
  layers <- SeuratObject::Layers(object[[assay]], search = NA)
  if (!counts_layer %in% layers) stop("exact counts layer required; join split layers explicitly with JoinLayers first")
  counts <- SeuratObject::LayerData(object[[assay]], layer = counts_layer)
  features <- rownames(counts); cells <- colnames(counts)
  .scx_ids(cells); .scx_ids(features)
  if (!length(cells) || !length(features)) stop("empty expression matrix")
  values <- .scx_values(counts)
  if (is.complex(values) || any(!is.finite(values)) || any(values < 0)) stop("counts must be finite real and nonnegative")
  rm(values)
  dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
  path <- file.path(normalizePath(dirname(path), winslash = "/", mustWork = TRUE), basename(path))
  work <- tempfile(".scx-stage-", tmpdir = dirname(path)); dir.create(work)
  stage <- file.path(work, "payload"); dir.create(stage)
  on.exit(if (!dir.exists(file.path(work, "previous"))) unlink(work, recursive = TRUE), add = TRUE)
  entries <- data.frame(path = c("cells.tsv.gz", "features.tsv.gz", "matrices/counts.mtx.gz", "metadata.schema.json"),
                        role = c("cells", "features", "counts", "metadata_schema"),
                        name = c("cells", "features", "counts", "metadata"))
  schema <- list(schema_version = "1.0",
                 cells = .scx_meta(object[[]][cells, , drop = FALSE], cells, "cell_id", file.path(stage, "cells.tsv.gz")),
                 features = .scx_meta(object[[assay]][[]][features, , drop = FALSE], features, "feature_id", file.path(stage, "features.tsv.gz")))
  writeLines(.scx_json(schema), file.path(stage, "metadata.schema.json"), useBytes = TRUE)
  .scx_mtx(Matrix::t(counts), file.path(stage, "matrices/counts.mtx.gz"))
  if (!is.null(normalized_layer)) {
    if (normalized_layer %in% layers) {
      normalized <- .scx_aligned(SeuratObject::LayerData(object[[assay]], layer = normalized_layer), features, cells)
      values <- .scx_values(normalized)
      if (is.complex(values) || any(!is.finite(values))) stop("normalized matrix must be finite real")
      rm(values)
      .scx_mtx(Matrix::t(normalized), file.path(stage, "matrices/normalized.mtx.gz"))
      entries <- rbind(entries, data.frame(path = "matrices/normalized.mtx.gz", role = "normalized", name = "normalized"))
    } else warning("normalized layer absent; exporting counts only")
  }
  for (name in reductions) {
    .scx_name(name)
    reduction <- object[[name]]
    if (SeuratObject::DefaultAssay(reduction) != assay) stop("embedding belongs to a different assay: ", name)
    x <- .scx_aligned(SeuratObject::Embeddings(reduction), cells)
    if (!ncol(x) || !is.numeric(x) || any(!is.finite(x))) stop("invalid embedding")
    table <- data.frame(cell_id = cells, x, check.names = FALSE)
    names(table) <- c("cell_id", paste0("dim_", seq_len(ncol(x))))
    relative <- paste0("embeddings/", name, ".tsv.gz")
    # Explicit 17-digit formatting before write.table (which formats doubles differently).
    table[-1] <- lapply(table[-1], function(v) sprintf("%.17g", v))
    .scx_tsv(table, file.path(stage, relative))
    entries <- rbind(entries, data.frame(path = relative, role = "embedding", name = name))
  }
  for (name in graphs) {
    .scx_name(name)
    graph <- object[[name]]
    if (SeuratObject::DefaultAssay(graph) != assay) stop("graph belongs to a different assay: ", name)
    x <- .scx_aligned(graph, cells, cells)
    values <- .scx_values(x)
    if (is.complex(values) || any(!is.finite(values))) stop("graph must be finite real")
    rm(values)
    relative <- paste0("graphs/", name, ".mtx.gz")
    .scx_mtx(x, file.path(stage, relative))
    entries <- rbind(entries, data.frame(path = relative, role = "cell_graph", name = name))
  }
  con <- file(file.path(stage, "manifest.tsv"), "wt", encoding = "UTF-8")
  writeLines("# scx_version=0.1-alpha", con)
  write.table(entries, con, sep = "\t", row.names = FALSE, quote = FALSE)
  close(con)
  if (warn_scope) warning("SCX exports one assay and selected layers, metadata, embeddings and graphs; identities, other layers, loadings and analysis history are not exported")
  .scx_publish(work, path, overwrite)
  invisible(path)
}

#' Import an SCX dataset via the native R validator and typed metadata decoder.
#' @export
read_scx_seurat <- function(path, assay = "RNA", python = NULL, assay_class = c("Assay5", "Assay")) {
  assay_class <- match.arg(assay_class)
  checked <- .scx_inspect(path, retain = TRUE)
  manifest <- checked$manifest
  ids <- checked$cells; genes <- checked$features
  meta <- checked$meta; feature_meta <- checked$feature_meta
  load_matrix <- function(relative) checked$matrices[[relative]]
  counts <- Matrix::t(load_matrix("matrices/counts.mtx.gz")); dimnames(counts) <- list(genes, ids)
  assay_object <- if (assay_class == "Assay5") SeuratObject::CreateAssay5Object(counts = counts) else SeuratObject::CreateAssayObject(counts = counts)
  object <- SeuratObject::CreateSeuratObject(assay_object, assay = assay, meta.data = meta)
  if (!identical(rownames(object[[assay]]), genes)) stop("Seurat altered feature IDs; import refused")
  if (ncol(feature_meta)) object[[assay]] <- SeuratObject::AddMetaData(object[[assay]], feature_meta)
  for (i in seq_len(nrow(manifest))) {
    entry <- manifest[i, ]
    if (entry$role == "normalized") {
      x <- Matrix::t(load_matrix(entry$path)); dimnames(x) <- list(genes, ids)
      SeuratObject::LayerData(object, assay = assay, layer = "data") <- x
    } else if (entry$role == "embedding") {
      x <- checked$embeddings[[entry$path]]; rownames(x) <- ids
      key <- paste0("SCX", i, "_"); colnames(x) <- paste0(key, seq_len(ncol(x)))
      object[[entry$name]] <- SeuratObject::CreateDimReducObject(x, assay = assay, key = key)
    } else if (entry$role == "cell_graph") {
      x <- load_matrix(entry$path); dimnames(x) <- list(ids, ids)
      graph <- SeuratObject::as.Graph(x); SeuratObject::DefaultAssay(graph) <- assay
      object[[entry$name]] <- graph
    }
  }
  # Assay/feature-metadata setters may regenerate QC columns. Restore the
  # validated SCX table after every setter to retain exactly the source columns.
  object@meta.data <- meta
  object
}

.scx_decode_frame <- function(table, spec) {
  frame <- data.frame(row.names = table[[1]])
  if (is.null(spec)) {
    for (name in names(table)[-1]) frame[[name]] <- table[[name]]
    return(frame)
  }
  convert <- function(values, dtype) {
    missing <- vapply(values, is.null, logical(1))
    if (dtype %in% c("object", "str", "string")) {
      x <- rep(NA_character_, length(values))
    } else if (dtype %in% c("bool", "boolean")) {
      x <- rep(NA, length(values))
    } else if (dtype %in% c("int8", "int16", "int32", "Int8", "Int16", "Int32", "uint8", "uint16", "UInt8", "UInt16")) {
      x <- rep(NA_integer_, length(values))
      if (any(vapply(values[!missing], function(v) v <= -.Machine$integer.max - 1, logical(1)))) stop("R cannot represent INT_MIN without losing missingness")
    } else if (dtype %in% c("float32", "float64", "Float32", "Float64")) {
      x <- rep(NA_real_, length(values))
    } else stop("SCX dtype not safely representable in native R: ", dtype)
    x[!missing] <- unlist(values[!missing], use.names = FALSE)
    if (is.integer(x)) x <- as.integer(x)
    x
  }
  for (column in spec$columns) {
    values <- jsonlite::fromJSON(paste0("[", paste(table[[column$name]], collapse = ","), "]"), simplifyVector = FALSE)
    if (column$dtype == "category") {
      levels <- convert(column$categories, column$categories_dtype)
      codes <- vapply(values, function(x) if (is.null(x)) NA_integer_ else as.integer(x) + 1L, integer(1))
      # R factors have character levels; numeric categories cannot retain their type.
      if (!is.character(levels)) stop("numeric/boolean categorical levels are unsupported by R factors")
      x <- structure(codes, levels = levels, class = if (column$ordered) c("ordered", "factor") else "factor")
    } else x <- convert(values, column$dtype)
    frame[[column$name]] <- x
  }
  frame
}

#' Write the basic SCX profile, optionally including analysis coordinates/graphs.
#' @export
write_scx <- function(object, path, counts = "counts", normalized = "data",
                      analysis = FALSE, overwrite = FALSE,
                      assay = SeuratObject::DefaultAssay(object)) {
  if (!is.logical(analysis) || length(analysis) != 1L || is.na(analysis)) stop("analysis must be TRUE or FALSE")
  omitted <- character()
  if (!analysis && (length(SeuratObject::Reductions(object)) || length(SeuratObject::Graphs(object))))
    omitted <- c(omitted, "embeddings/graphs (include with analysis=TRUE)")
  if (length(SeuratObject::Assays(object)) > 1L) omitted <- c(omitted, "other assays")
  layers <- SeuratObject::Layers(object[[assay]], search = NA)
  if (length(setdiff(layers, c(counts, normalized)))) omitted <- c(omitted, "other expression layers")
  loadings <- any(vapply(SeuratObject::Reductions(object), function(name)
    length(SeuratObject::Loadings(object[[name]])) > 0L, logical(1)))
  if (length(object@commands) || length(object@misc) || loadings)
    omitted <- c(omitted, "analysis internals outside the SCX profile")
  result <- write_scx_seurat(object, path, assay = assay, counts_layer = counts,
    normalized_layer = if (identical(counts, normalized)) NULL else normalized,
    reductions = if (analysis) SeuratObject::Reductions(object) else character(),
    graphs = if (analysis) SeuratObject::Graphs(object) else character(),
    overwrite = overwrite, warn_scope = FALSE)
  if (length(omitted)) warning("SCX omitted: ", paste(omitted, collapse = "; "), call. = FALSE)
  invisible(result)
}

#' Validate and read an SCX directory into Seurat.
#' @export
read_scx <- function(path, assay = "RNA", assay_class = c("Assay5", "Assay"))
  read_scx_seurat(path, assay = assay, assay_class = match.arg(assay_class))

# Resolve nonexistent parent segments before creating anything or checking containment.
.scx_tsv_target <- function(output) {
  if (!is.character(output) || length(output) != 1L || is.na(output) || !nzchar(output)) stop("output must be one file path")
  output <- path.expand(output)
  parent <- dirname(output); suffix <- basename(output)
  while (!dir.exists(parent)) {
    next_parent <- dirname(parent)
    if (identical(next_parent, parent)) stop("cannot resolve output parent")
    suffix <- file.path(basename(parent), suffix)
    parent <- next_parent
  }
  target <- normalizePath(parent, winslash="/", mustWork=TRUE)
  if (.Platform$OS.type == "windows") suffix <- chartr("\\", "/", suffix)
  for (part in strsplit(suffix, "/", fixed=TRUE)[[1]]) {
    if (part == "..") target <- dirname(target)
    else if (part != "." && nzchar(part)) target <- file.path(target, part)
  }
  target
}

.scx_tsv_select <- function(ids, requested, label) {
  if (is.null(requested)) return(seq_along(ids))
  if (!is.character(requested) || !length(requested) || anyNA(requested) || anyDuplicated(requested))
    stop(label, " must be nonempty unique character IDs")
  selected <- match(requested, ids)
  if (anyNA(selected)) stop("unknown ", label, " IDs: ", paste(head(requested[is.na(selected)], 5L), collapse=", "))
  selected
}

.scx_tsv_field <- function(x) ifelse(grepl('["\t\r\n]', x), paste0('"', gsub('"', '""', x, fixed=TRUE), '"'), x)

#' Export an SCX expression matrix as CELL x FEATURE TSV or TSV.gz.
#' @export
to_tsv <- function(path, output, matrix="counts", cells=NULL, features=NULL) {
  if (!is.character(matrix) || length(matrix) != 1L || is.na(matrix) || !matrix %in% c("counts","normalized"))
    stop("matrix must be counts or normalized")
  root <- normalizePath(path, winslash="/", mustWork=TRUE)
  target <- .scx_tsv_target(output)
  root_key <- root; target_key <- target
  if (.Platform$OS.type == "windows") { root_key <- tolower(root); target_key <- tolower(target) }
  if (target_key == root_key || startsWith(target_key, paste0(root_key,"/"))) stop("TSV output must be outside the input SCX directory")
  if (.scx_exists(target)) stop("output already exists; choose a new path")
  data <- .scx_inspect(root, retain_expression=matrix)
  entry <- data$manifest[data$manifest$role == matrix, , drop=FALSE]
  if (!nrow(entry)) stop("SCX has no normalized matrix")
  values <- data$matrices[[entry$path]]
  data$matrices <- NULL
  rows <- .scx_tsv_select(data$cells, cells, "cells")
  columns <- .scx_tsv_select(data$features, features, "features")
  target <- .scx_output_path(target)
  stage <- tempfile(".scx-tsv-", tmpdir=dirname(target))
  con <- NULL; input <- NULL; destination <- NULL
  on.exit({
    if (!is.null(con)) close(con)
    if (!is.null(input)) close(input)
    if (!is.null(destination)) close(destination)
    unlink(stage)
  }, add=TRUE)
  con <- if (endsWith(target,".gz")) gzfile(stage,"wt",encoding="UTF-8") else file(stage,"wt",encoding="UTF-8")
  withCallingHandlers({
    # CSR gives direct access to each row's stored entries. Keep the source
    # sparse; the only full-width output buffer is a vector of text fields.
    values <- methods::as(values,"RsparseMatrix")
    column_map <- integer(ncol(values))
    column_map[columns] <- seq_along(columns)
    writeLines(paste(.scx_tsv_field(c("cell_id",data$features[columns])), collapse="\t"), con, useBytes=TRUE)
    for (row in rows) {
      fields <- rep.int("0",length(columns))
      from <- values@p[row]; to <- values@p[row+1]
      if (from < to) {
        entries <- seq.int(from+1L,to)
        positions <- column_map[values@j[entries]+1L]
        keep <- positions > 0L
        # Include explicit stored zeros as well: sprintf retains signed zero.
        fields[positions[keep]] <- sprintf("%.17g",values@x[entries[keep]])
      }
      writeLines(paste(c(.scx_tsv_field(data$cells[row]), fields),collapse="\t"), con, useBytes=TRUE)
    }
    close(con); con <- NULL
  }, warning=function(w) stop(conditionMessage(w),call.=FALSE))
  lock <- .scx_lock_path(target)
  lock_con <- tryCatch(suppressWarnings(file(lock,"wx")), error=function(e) stop("output is locked: ",lock))
  reserved <- FALSE; published <- FALSE
  on.exit(if (!reserved || published) unlink(lock), add=TRUE)
  tryCatch(writeLines(.scx_json(list(pid=Sys.getpid(), output=target, mode="tsv-copy")),lock_con), finally=close(lock_con))
  tryCatch({
    # Exclusive binary creation refuses existing files, links and racing writers.
    destination <- suppressWarnings(file(target,"wxb"))
    reserved <- TRUE
    input <- file(stage,"rb")
    repeat {
      bytes <- readBin(input,"raw",1024L*1024L)
      if (!length(bytes)) break
      writeBin(bytes,destination)
    }
    close(destination); destination <- NULL
    close(input); input <- NULL
    if (digest::digest(stage,file=TRUE,algo="sha256") != digest::digest(target,file=TRUE,algo="sha256")) stop("TSV copy checksum mismatch")
    published <- TRUE
  }, error=function(e) {
    if (reserved) stop("Incomplete TSV retained at ",target,"; lock retained at ",lock,". ",conditionMessage(e),call.=FALSE)
    stop("output already exists or cannot be created: ",target,". ",conditionMessage(e),call.=FALSE)
  })
  invisible(target)
}

# Pure R backend for the generated standalone script, not the installed package.
# Deliberately refuses replacement: base R has no portable no-replace dir rename.
.scx_native <- function(name, ...) {
  if (name != "scx_check_gzip") stop("Native helper unavailable in standalone mode")
  path <- list(...)[[1]]
  .scx_check_gzip_r(path)
}

.scx_symlink <- function(path) {
  link <- suppressWarnings(Sys.readlink(path))
  length(link) == 1L && !is.na(link) && nzchar(link)
}

.scx_check_gzip_r <- function(path) {
  # Verify a single gzip member's CRC and length with existing digest + base R.
  # Stream to scratch disk rather than retaining the decompressed matrix in RAM.
  input <- file(path, "rb")
  scratch <- tempfile("scx-gzip-")
  output <- NULL; decoded <- NULL
  on.exit({
    if (!is.null(decoded)) close(decoded)
    if (!is.null(output)) close(output)
    close(input)
    unlink(scratch)
  }, add = TRUE)
  size <- file.info(path)$size
  if (is.na(size) || size < 18) stop("truncated gzip")
  header <- readBin(input, "raw", 3L)
  if (!identical(header, as.raw(c(31, 139, 8)))) stop("invalid gzip header")
  seek(input, size - 8, origin = "start")
  trailer <- readBin(input, "raw", 8L)
  expected_crc <- paste(sprintf("%02x", as.integer(rev(trailer[1:4]))), collapse = "")
  expected_size <- sum(as.integer(trailer[5:8]) * 256^(0:3))
  output <- file(scratch, "wb")
  decoded <- gzfile(path, "rb")
  total <- 0
  withCallingHandlers(repeat {
    chunk <- readBin(decoded, "raw", 1024L * 1024L)
    if (!length(chunk)) break
    total <- total + length(chunk)
    writeBin(chunk, output)
  }, warning = function(w) stop(conditionMessage(w), call. = FALSE))
  close(output)
  # Don't call isOpen() on a closed, invalid connection in the exit handler.
  output <- NULL
  if (total %% 2^32 != expected_size || digest::digest(scratch, file = TRUE, algo = "crc32") != expected_crc)
    stop("gzip CRC/length mismatch; corrupt, truncated or unsupported concatenated gzip")
  invisible(TRUE)
}

.scx_copy <- function(source, target) {
  dir.create(dirname(target), recursive = TRUE, showWarnings = FALSE)
  if (!isTRUE(file.copy(source, target, overwrite = FALSE, copy.mode = TRUE))) stop("copy failed: ", target)
  if (digest::digest(source, file = TRUE, algo = "sha256") != digest::digest(target, file = TRUE, algo = "sha256"))
    stop("copied file checksum mismatch: ", target)
}

.scx_publish <- function(stage, path, overwrite) {
  if (overwrite) stop("Standalone R refuses overwrite=TRUE; choose a new output directory. The installed package supports staged replacement.")
  path <- .scx_output_path(path)
  lock <- .scx_lock_path(path)
  con <- tryCatch(suppressWarnings(file(lock, "wx", encoding = "UTF-8")), error = function(e)
    stop("output is locked or lock cannot be created: ", lock, call. = FALSE))
  reserved <- FALSE; published <- FALSE
  on.exit({
    if (!reserved || published) unlink(lock)
    # If interrupted during copy, keep the incomplete directory and lock.
    # The upstream writer cleans its private staging files; no old output is touched.
  }, add = TRUE)
  tryCatch(writeLines(.scx_json(list(pid = Sys.getpid(), output = path, mode = "standalone-copy")), con),
           finally = close(con))
  payload <- file.path(stage, "payload")
  validate_scx(payload)
  .scx_destination(path, FALSE)
  # mkdir reserves the leaf atomically and cannot replace any existing entry.
  if (!dir.create(path, showWarnings = FALSE)) stop("output already exists or cannot be reserved: ", path)
  reserved <- TRUE
  tryCatch({
    manifest <- .scx_manifest(payload)
    for (relative in manifest$path) .scx_copy(file.path(payload, relative), file.path(path, relative))
    # No reader can accept the new directory until the manifest appears last.
    pending <- file.path(path, ".scx-manifest-pending")
    .scx_copy(file.path(payload, "manifest.tsv"), pending)
    if (!file.rename(pending, file.path(path, "manifest.tsv"))) stop("manifest publication failed")
    published <- TRUE
  }, error = function(e) stop("Incomplete output retained at ", path, "; lock retained at ", lock,
       ". Original inputs are unchanged. Choose a new path; see standalone recovery guidance. ",
       conditionMessage(e), call. = FALSE))
  invisible(path)
}

# Reject unsupported replacement before doing any data export work.
.scx_write_impl <- write_scx
write_scx <- function(object, path, counts = "counts", normalized = "data",
                      analysis = FALSE, overwrite = FALSE,
                      assay = SeuratObject::DefaultAssay(object)) {
  if (!identical(overwrite, FALSE)) stop("Standalone R requires overwrite=FALSE; choose a new output directory")
  .scx_write_impl(object, path, counts = counts, normalized = normalized,
                  analysis = analysis, overwrite = FALSE, assay = assay)
}

for (.name in c("SCX_VERSION", "read_scx", "write_scx", "validate_scx", "to_tsv")) assign(.name, get(.name), envir=.target)
invisible(NULL)
})(environment())
